def defangIPaddr(address: str) -> str:
    # Initialize an empty list to collect characters and '[.]'
    res = []
    for c in address:
        if c == '.':
            # Replace period with '[.]'
            res.append('[.]')
        else:
            # Copy the digit as is
            res.append(c)
    # Join result list into a single string and return
    return ''.join(res)
